const e={"s10-meet~idea":{level:10,bands:[3],topics:["stop:s10-meet","strand:sentence"],key:"stop:s10-meet",where:"Sentence 10 · Sentences on demand",route:"#/stop/s10-meet",cta:"Meet the brief on the Sentence road",id:"s10-meet~idea",kind:"lesson",src:"stop:s10-meet#why",title:"Meet the brief",body:"A brief is a set of rules a sentence must meet, all at once. Check each rule separately against each sentence: Is it one sentence? How does it begin — a subordinate clause has its own subject and verb? Is there a list of three, in matching shapes? Does each semicolon join two complete sentences, or separate list items that already contain commas?",more:"I can choose the sentence that meets every rule of a brief."},"s10-meet~story":{level:10,bands:[3],topics:["stop:s10-meet","strand:sentence"],key:"stop:s10-meet",where:"Sentence 10 · Sentences on demand",route:"#/stop/s10-meet",cta:"Meet the brief on the Sentence road",id:"s10-meet~story",kind:"story",src:"stop:s10-meet#story",title:"Meet the brief",body:'Quill has a job card: "One sentence. Start with a when-clause. Include three things." Quill grins. "A writer can build any sentence to order — if every rule is checked, one at a time."',more:"Taught at: Sentence 10 · Sentences on demand — Meet the brief."},"s10-meet~eg":{level:10,bands:[3],topics:["stop:s10-meet","strand:sentence"],key:"stop:s10-meet",where:"Sentence 10 · Sentences on demand",route:"#/stop/s10-meet",cta:"Meet the brief on the Sentence road",id:"s10-meet~eg",kind:"example",src:"stop:s10-meet#example",title:"Meet the brief: for example",body:"Brief: begins with a subordinate clause; contains a list of three. · When the storm passed, we found branches, leaves and a broken kite.",more:"Taught at: Sentence 10 · Sentences on demand — Meet the brief."},"s10-meet~q0":{level:10,bands:[3],topics:["stop:s10-meet","strand:sentence"],key:"stop:s10-meet",where:"Sentence 10 · Sentences on demand",route:"#/stop/s10-meet",cta:"Meet the brief on the Sentence road",id:"s10-meet~q0",kind:"question",src:"item:s10-meet#0",title:"Meet the brief",play:{q:"Which sentence meets ALL of these rules: it begins with a subordinate clause; it contains a list of three?",opts:["When the storm passed, we found branches, leaves and a broken kite.","After the storm, we found branches, leaves and a broken kite.","When the storm passed, we found branches and a broken kite.","We found branches, leaves and a broken kite when the storm passed."],after:""},more:"Taught at: Sentence 10 · Sentences on demand — Meet the brief."},"s10-meet~q1":{level:10,bands:[3],topics:["stop:s10-meet","strand:sentence"],key:"stop:s10-meet",where:"Sentence 10 · Sentences on demand",route:"#/stop/s10-meet",cta:"Meet the brief on the Sentence road",id:"s10-meet~q1",kind:"question",src:"item:s10-meet#1",title:"Meet the brief",play:{q:"Which sentence meets ALL of these rules: it is one sentence; it uses a semicolon correctly?",opts:["The fox was hungry; the henhouse was locked.","The fox was hungry; because the henhouse was locked.","The fox was hungry. The henhouse was locked tight.","The fox was hungry, and the henhouse was locked."],after:""},more:"Taught at: Sentence 10 · Sentences on demand — Meet the brief."},"s10-meet~q2":{level:10,bands:[3],topics:["stop:s10-meet","strand:sentence"],key:"stop:s10-meet",where:"Sentence 10 · Sentences on demand",route:"#/stop/s10-meet",cta:"Meet the brief on the Sentence road",id:"s10-meet~q2",kind:"question",src:"item:s10-meet#2",title:"Meet the brief",play:{q:"Which sentence meets ALL of these rules: it begins with an -ing phrase; it uses a semicolon correctly?",opts:["Hearing the whistle, Bobbie ran to the fence; the train was coming.","Hearing the whistle, Bobbie ran to the fence, for the train was coming.","When she heard the whistle, Bobbie ran to the fence; the train was coming.","Hearing the whistle; Bobbie ran to the fence."],after:""},more:"Taught at: Sentence 10 · Sentences on demand — Meet the brief."},"s10-meet~q3":{level:10,bands:[3],topics:["stop:s10-meet","strand:sentence"],key:"stop:s10-meet",where:"Sentence 10 · Sentences on demand",route:"#/stop/s10-meet",cta:"Meet the brief on the Sentence road",id:"s10-meet~q3",kind:"question",src:"item:s10-meet#3",title:"Meet the brief",play:{q:"Which sentence meets ALL of these rules: it contains a list of three; the list is parallel?",opts:["Jo liked writing plays, reading novels and climbing trees.","Jo liked writing plays, reading novels and to climb trees.","Jo liked writing plays and reading novels in the attic.","Jo liked to write plays, reading novels and climbing trees."],after:""},more:"Taught at: Sentence 10 · Sentences on demand — Meet the brief."},"s10-meet~q4":{level:10,bands:[3],topics:["stop:s10-meet","strand:sentence"],key:"stop:s10-meet",where:"Sentence 10 · Sentences on demand",route:"#/stop/s10-meet",cta:"Meet the brief on the Sentence road",id:"s10-meet~q4",kind:"question",src:"item:s10-meet#4",title:"Meet the brief",play:{q:"Which sentence meets ALL of these rules: it is one sentence; it begins with a subordinate clause; it uses a semicolon correctly?",opts:["Although the boat leaked, Rat kept rowing; Mole bailed out the water.","Although the boat leaked; Rat kept rowing and Mole bailed out the water.","Although the boat leaked, Rat kept rowing. Mole bailed it out.","Rat kept rowing although the boat leaked; Mole bailed out the water."],after:""},more:"Taught at: Sentence 10 · Sentences on demand — Meet the brief."},"s10-meet~q5":{level:10,bands:[3],topics:["stop:s10-meet","strand:sentence"],key:"stop:s10-meet",where:"Sentence 10 · Sentences on demand",route:"#/stop/s10-meet",cta:"Meet the brief on the Sentence road",id:"s10-meet~q5",kind:"question",src:"item:s10-meet#5",title:"Meet the brief",play:{q:"Which sentence meets ALL of these rules: it begins with a prepositional phrase; it contains a list of three?",opts:["In the old trunk, Anne found ribbons, letters and a silver locket.","Opening the old trunk, Anne found ribbons, letters and a silver locket.","In the old trunk, Anne found ribbons and a silver locket.","Anne found ribbons, letters and a silver locket in the old trunk."],after:""},more:"Taught at: Sentence 10 · Sentences on demand — Meet the brief."},"s10-meet~q6":{level:10,bands:[3],topics:["stop:s10-meet","strand:sentence"],key:"stop:s10-meet",where:"Sentence 10 · Sentences on demand",route:"#/stop/s10-meet",cta:"Meet the brief on the Sentence road",id:"s10-meet~q6",kind:"question",src:"item:s10-meet#6",title:"Meet the brief",play:{q:"Which sentence meets ALL of these rules: it is one sentence; it is periodic: the main clause comes last?",opts:["After three days of searching the hills, the shepherd found his lamb.","The shepherd found his lamb after three days of searching the hills.","After three days of searching the hills. Then the shepherd found his lamb.","The shepherd searched the hills for three days, and he found his lamb."],after:""},more:"Taught at: Sentence 10 · Sentences on demand — Meet the brief."},"s10-meet~q7":{level:10,bands:[3],topics:["stop:s10-meet","strand:sentence"],key:"stop:s10-meet",where:"Sentence 10 · Sentences on demand",route:"#/stop/s10-meet",cta:"Meet the brief on the Sentence road",id:"s10-meet~q7",kind:"question",src:"item:s10-meet#7",title:"Meet the brief",play:{q:"Which sentence meets ALL of these rules: it lists three places; semicolons separate list items that contain commas?",opts:["We visited Pune, in India; Paris, in France; and Lima, in Peru.","We visited Pune, in India, Paris, in France, and also Lima, in Peru.","We visited Pune, in India; and Paris, in France.","We visited Pune, in India; Paris, in France; Lima, in Peru; and Delhi."],after:""},more:"Taught at: Sentence 10 · Sentences on demand — Meet the brief."},"s10-meet~q8":{level:10,bands:[3],topics:["stop:s10-meet","strand:sentence"],key:"stop:s10-meet",where:"Sentence 10 · Sentences on demand",route:"#/stop/s10-meet",cta:"Meet the brief on the Sentence road",id:"s10-meet~q8",kind:"question",src:"item:s10-meet#8",title:"Meet the brief",play:{q:"Which sentence meets ALL of these rules: it begins with a subordinate clause; it contains a list of three; the list is parallel?",opts:["Before the guests arrived, we swept the floor, set the table and lit the candles.","Before the guests arrived, we swept the floor, set the table and the candles were lit.","Before the guests’ arrival, we swept the floor, set the table and lit the candles.","We swept the floor, set the table and lit the candles before the guests arrived."],after:""},more:"Taught at: Sentence 10 · Sentences on demand — Meet the brief."},"s10-meet~q9":{level:10,bands:[3],topics:["stop:s10-meet","strand:sentence"],key:"stop:s10-meet",where:"Sentence 10 · Sentences on demand",route:"#/stop/s10-meet",cta:"Meet the brief on the Sentence road",id:"s10-meet~q9",kind:"question",src:"item:s10-meet#9",title:"Meet the brief",play:{q:"Which sentence meets ALL of these rules: it is one sentence; it begins with an -ing phrase; it contains a list of three?",opts:["Grinning widely, Tom showed us a marble, a dead rat and a key.","Grinning widely, Tom showed us a marble and a key.","Tom grinned widely and showed us a marble, a dead rat and a key.","Grinning widely, Tom showed us a marble, a dead rat and a key. Then he ran."],after:""},more:"Taught at: Sentence 10 · Sentences on demand — Meet the brief."},"s10-meet~q10":{level:10,bands:[3],topics:["stop:s10-meet","strand:sentence"],key:"stop:s10-meet",where:"Sentence 10 · Sentences on demand",route:"#/stop/s10-meet",cta:"Meet the brief on the Sentence road",id:"s10-meet~q10",kind:"question",src:"item:s10-meet#10",title:"Meet the brief",play:{q:"Which sentence meets ALL of these rules: it is one sentence; it begins with an adverb; it uses a semicolon correctly?",opts:["Slowly, the tide went out; the rock pools shone in the sun.","Slowly, the tide went out, and the rock pools shone in the sun.","As the tide went out slowly; the rock pools shone in the sun.","The tide went out slowly; the rock pools shone in the sun."],after:""},more:"Taught at: Sentence 10 · Sentences on demand — Meet the brief."},"s10-meet~q11":{level:10,bands:[3],topics:["stop:s10-meet","strand:sentence"],key:"stop:s10-meet",where:"Sentence 10 · Sentences on demand",route:"#/stop/s10-meet",cta:"Meet the brief on the Sentence road",id:"s10-meet~q11",kind:"question",src:"item:s10-meet#11",title:"Meet the brief",play:{q:"Which sentence meets ALL of these rules: it is one sentence; it begins with a subordinate clause; it contains a list of three; it uses a semicolon correctly?",opts:["When winter came, the birds left, the pond froze and the fields turned white; only the robin stayed.","When winter came, the birds left, the pond froze and the fields turned white. Only the robin stayed behind.","When winter came, the birds left and the pond froze; only the robin stayed.","The birds left, the pond froze and the fields turned white when winter came; only the robin stayed."],after:""},more:"Taught at: Sentence 10 · Sentences on demand — Meet the brief."},"s10-check~idea":{level:10,bands:[3],topics:["stop:s10-check","strand:sentence"],key:"stop:s10-check",where:"Sentence 10 · Sentences on demand",route:"#/stop/s10-check",cta:"Check against the brief on the Sentence road",id:"s10-check~idea",kind:"lesson",src:"stop:s10-check#why",title:"Check against the brief",body:"Checking your own sentence against a brief is the same skill as building one. Go rule by rule: count the sentences (full stops), look at the first words (a subordinate clause has a joining word like when, because or although, then a subject and a verb), count the list, and test each semicolon — could the words on each side stand alone?",more:"I can find the rule a sentence misses."},"s10-check~story":{level:10,bands:[3],topics:["stop:s10-check","strand:sentence"],key:"stop:s10-check",where:"Sentence 10 · Sentences on demand",route:"#/stop/s10-check",cta:"Check against the brief on the Sentence road",id:"s10-check~story",kind:"story",src:"stop:s10-check#story",title:"Check against the brief",body:'Quill is the editor today, with a red pencil and a brief pinned to the desk. "Each of these sentences nearly made it," says Quill. "Find the one rule each one missed."',more:"Taught at: Sentence 10 · Sentences on demand — Check against the brief."},"s10-check~eg":{level:10,bands:[3],topics:["stop:s10-check","strand:sentence"],key:"stop:s10-check",where:"Sentence 10 · Sentences on demand",route:"#/stop/s10-check",cta:"Check against the brief on the Sentence road",id:"s10-check~eg",kind:"example",src:"stop:s10-check#example",title:"Check against the brief: for example",body:"Brief: one sentence; begins with a subordinate clause; a list of three; a correct semicolon. · If the sun shines, we will swim and sail; the boat is ready. → misses the list of three",more:"Taught at: Sentence 10 · Sentences on demand — Check against the brief."},"s10-check~q0":{level:10,bands:[3],topics:["stop:s10-check","strand:sentence"],key:"stop:s10-check",where:"Sentence 10 · Sentences on demand",route:"#/stop/s10-check",cta:"Check against the brief on the Sentence road",id:"s10-check~q0",kind:"question",src:"item:s10-check#0",title:"Check against the brief",play:{q:"The brief: it is one sentence, begins with a subordinate clause, contains a list of three, and uses a semicolon correctly. Which part of the brief does this sentence miss? “If the sun shines, we will swim, fish and sail, the boat is ready.”",opts:["uses a semicolon correctly","is one sentence","begins with a subordinate clause","contains a list of three"],after:""},more:"Taught at: Sentence 10 · Sentences on demand — Check against the brief."},"s10-check~q1":{level:10,bands:[3],topics:["stop:s10-check","strand:sentence"],key:"stop:s10-check",where:"Sentence 10 · Sentences on demand",route:"#/stop/s10-check",cta:"Check against the brief on the Sentence road",id:"s10-check~q1",kind:"question",src:"item:s10-check#1",title:"Check against the brief",play:{q:"The brief: it is one sentence, begins with a subordinate clause, contains a list of three, and uses a semicolon correctly. Which part of the brief does this sentence miss? “If the sun shines, we will swim and sail; the boat is ready.”",opts:["contains a list of three","is one sentence","begins with a subordinate clause","uses a semicolon correctly"],after:""},more:"Taught at: Sentence 10 · Sentences on demand — Check against the brief."},"s10-check~q2":{level:10,bands:[3],topics:["stop:s10-check","strand:sentence"],key:"stop:s10-check",where:"Sentence 10 · Sentences on demand",route:"#/stop/s10-check",cta:"Check against the brief on the Sentence road",id:"s10-check~q2",kind:"question",src:"item:s10-check#2",title:"Check against the brief",play:{q:"The brief: it is one sentence, begins with a subordinate clause, contains a list of three, and uses a semicolon correctly. Which part of the brief does this sentence miss? “In the sunshine, we will swim, fish and sail; the boat is ready.”",opts:["begins with a subordinate clause","is one sentence","contains a list of three","uses a semicolon correctly"],after:""},more:"Taught at: Sentence 10 · Sentences on demand — Check against the brief."},"s10-check~q3":{level:10,bands:[3],topics:["stop:s10-check","strand:sentence"],key:"stop:s10-check",where:"Sentence 10 · Sentences on demand",route:"#/stop/s10-check",cta:"Check against the brief on the Sentence road",id:"s10-check~q3",kind:"question",src:"item:s10-check#3",title:"Check against the brief",play:{q:"The brief: it is one sentence, begins with a subordinate clause, contains a list of three, and uses a semicolon correctly. Which part of the brief does this sentence miss? “If the sun shines, we will swim, fish and sail; the boat is ready. Bring a towel.”",opts:["is one sentence","begins with a subordinate clause","contains a list of three","uses a semicolon correctly"],after:""},more:"Taught at: Sentence 10 · Sentences on demand — Check against the brief."},"s10-check~q4":{level:10,bands:[3],topics:["stop:s10-check","strand:sentence"],key:"stop:s10-check",where:"Sentence 10 · Sentences on demand",route:"#/stop/s10-check",cta:"Check against the brief on the Sentence road",id:"s10-check~q4",kind:"question",src:"item:s10-check#4",title:"Check against the brief",play:{q:"The brief: it is one sentence, begins with a subordinate clause, contains a list of three, and uses a semicolon correctly. Which part of the brief does this sentence miss? “Because the path was steep; we carried water, bread and rope, and nobody complained.”",opts:["uses a semicolon correctly","is one sentence","begins with a subordinate clause","contains a list of three"],after:""},more:"Taught at: Sentence 10 · Sentences on demand — Check against the brief."},"s10-check~q5":{level:10,bands:[3],topics:["stop:s10-check","strand:sentence"],key:"stop:s10-check",where:"Sentence 10 · Sentences on demand",route:"#/stop/s10-check",cta:"Check against the brief on the Sentence road",id:"s10-check~q5",kind:"question",src:"item:s10-check#5",title:"Check against the brief",play:{q:"The brief: it is one sentence, begins with a subordinate clause, contains a list of three, and uses a semicolon correctly. Which part of the brief does this sentence miss? “Carrying water, bread and rope, we climbed the steep path; nobody complained.”",opts:["begins with a subordinate clause","is one sentence","contains a list of three","uses a semicolon correctly"],after:""},more:"Taught at: Sentence 10 · Sentences on demand — Check against the brief."},"s10-check~q6":{level:10,bands:[3],topics:["stop:s10-check","strand:sentence"],key:"stop:s10-check",where:"Sentence 10 · Sentences on demand",route:"#/stop/s10-check",cta:"Check against the brief on the Sentence road",id:"s10-check~q6",kind:"question",src:"item:s10-check#6",title:"Check against the brief",play:{q:"The brief: it is one sentence, begins with a subordinate clause, contains a list of three, and uses a semicolon correctly. Which part of the brief does this sentence miss? “Because the path was steep, we carried water and rope; nobody complained.”",opts:["contains a list of three","is one sentence","begins with a subordinate clause","uses a semicolon correctly"],after:""},more:"Taught at: Sentence 10 · Sentences on demand — Check against the brief."},"s10-check~q7":{level:10,bands:[3],topics:["stop:s10-check","strand:sentence"],key:"stop:s10-check",where:"Sentence 10 · Sentences on demand",route:"#/stop/s10-check",cta:"Check against the brief on the Sentence road",id:"s10-check~q7",kind:"question",src:"item:s10-check#7",title:"Check against the brief",play:{q:"The brief: it is one sentence, begins with a subordinate clause, contains a list of three, and uses a semicolon correctly. Which part of the brief does this sentence miss? “Because the path was steep, we carried water, bread and rope. Nobody complained; we sang.”",opts:["is one sentence","begins with a subordinate clause","contains a list of three","uses a semicolon correctly"],after:""},more:"Taught at: Sentence 10 · Sentences on demand — Check against the brief."},"s10-check~q8":{level:10,bands:[3],topics:["stop:s10-check","strand:sentence"],key:"stop:s10-check",where:"Sentence 10 · Sentences on demand",route:"#/stop/s10-check",cta:"Check against the brief on the Sentence road",id:"s10-check~q8",kind:"question",src:"item:s10-check#8",title:"Check against the brief",play:{q:"The brief: it is one sentence, begins with a subordinate clause, contains a list of three, and uses a semicolon correctly. Which part of the brief does this sentence miss? “When the circus came, we saw clowns, jugglers and a lion, it roared at us.”",opts:["uses a semicolon correctly","is one sentence","begins with a subordinate clause","contains a list of three"],after:""},more:"Taught at: Sentence 10 · Sentences on demand — Check against the brief."},"s10-check~q9":{level:10,bands:[3],topics:["stop:s10-check","strand:sentence"],key:"stop:s10-check",where:"Sentence 10 · Sentences on demand",route:"#/stop/s10-check",cta:"Check against the brief on the Sentence road",id:"s10-check~q9",kind:"question",src:"item:s10-check#9",title:"Check against the brief",play:{q:"The brief: it is one sentence, begins with a subordinate clause, contains a list of three, and uses a semicolon correctly. Which part of the brief does this sentence miss? “At the circus, we saw clowns, jugglers and a lion; it roared at us.”",opts:["begins with a subordinate clause","is one sentence","contains a list of three","uses a semicolon correctly"],after:""},more:"Taught at: Sentence 10 · Sentences on demand — Check against the brief."},"s10-check~q10":{level:10,bands:[3],topics:["stop:s10-check","strand:sentence"],key:"stop:s10-check",where:"Sentence 10 · Sentences on demand",route:"#/stop/s10-check",cta:"Check against the brief on the Sentence road",id:"s10-check~q10",kind:"question",src:"item:s10-check#10",title:"Check against the brief",play:{q:"The brief: it is one sentence, begins with a subordinate clause, contains a list of three, and uses a semicolon correctly. Which part of the brief does this sentence miss? “When the circus came, we saw clowns and a lion; it roared at us.”",opts:["contains a list of three","is one sentence","begins with a subordinate clause","uses a semicolon correctly"],after:""},more:"Taught at: Sentence 10 · Sentences on demand — Check against the brief."},"s10-check~q11":{level:10,bands:[3],topics:["stop:s10-check","strand:sentence"],key:"stop:s10-check",where:"Sentence 10 · Sentences on demand",route:"#/stop/s10-check",cta:"Check against the brief on the Sentence road",id:"s10-check~q11",kind:"question",src:"item:s10-check#11",title:"Check against the brief",play:{q:"The brief: it is one sentence, begins with a subordinate clause, contains a list of three, and uses a semicolon correctly. Which part of the brief does this sentence miss? “When the circus came, we saw clowns, jugglers and a lion; it roared. We cheered.”",opts:["is one sentence","begins with a subordinate clause","contains a list of three","uses a semicolon correctly"],after:""},more:"Taught at: Sentence 10 · Sentences on demand — Check against the brief."},"s10-check~q12":{level:10,bands:[3],topics:["stop:s10-check","strand:sentence"],key:"stop:s10-check",where:"Sentence 10 · Sentences on demand",route:"#/stop/s10-check",cta:"Check against the brief on the Sentence road",id:"s10-check~q12",kind:"question",src:"item:s10-check#12",title:"Check against the brief",play:{q:"The brief: it is one sentence, begins with a subordinate clause, contains a list of three, and uses a semicolon correctly. Which part of the brief does this sentence miss? “Although Toad promised; he bought a car, a boat and a caravan, and Rat sighed.”",opts:["uses a semicolon correctly","is one sentence","begins with a subordinate clause","contains a list of three"],after:""},more:"Taught at: Sentence 10 · Sentences on demand — Check against the brief."},"wr10-model~idea":{level:10,bands:[1,2,3],topics:["stop:wr10-model","strand:writing"],key:"stop:wr10-model",where:"Writing 10 · After a model",route:"#/desk/wr10-model",cta:"In the manner of… at the writing desk",id:"wr10-model~idea",kind:"lesson",src:"stop:wr10-model#why",title:"In the manner of…",body:"Read a model, notice what makes it special — its opening, its voice, its repeated phrases — then write your own piece that borrows those things. This is how writers have always learned.",more:"I can write a short piece in the manner of a classic I have read."},"wr10-model~story":{level:10,bands:[1,2,3],topics:["stop:wr10-model","strand:writing"],key:"stop:wr10-model",where:"Writing 10 · After a model",route:"#/desk/wr10-model",cta:"In the manner of… at the writing desk",id:"wr10-model~story",kind:"story",src:"stop:wr10-model#story",title:"In the manner of…",body:"Kipling wrote “How the Elephant got its Trunk”. What other “How the … got its …” stories are waiting to be written?",more:"Taught at: Writing 10 · After a model — In the manner of…"},"wr10-model~eg":{level:10,bands:[1,2,3],topics:["stop:wr10-model","strand:writing"],key:"stop:wr10-model",where:"Writing 10 · After a model",route:"#/desk/wr10-model",cta:"In the manner of… at the writing desk",id:"wr10-model~eg",kind:"example",src:"stop:wr10-model#example",title:"In the manner of…: for example",body:"A “Just So” story: How the Zebra got its Stripes. · A fable with a one-line moral.",more:"Taught at: Writing 10 · After a model — In the manner of…"},"wr10-model~p0":{level:10,bands:[1,2,3],topics:["stop:wr10-model","strand:writing"],key:"stop:wr10-model",where:"Writing 10 · After a model",route:"#/desk/wr10-model",cta:"In the manner of… at the writing desk",id:"wr10-model~p0",kind:"desk",src:"stop:wr10-model#prompt0",title:"A “Just So” story: How the … got its …",body:"The model · Your piece",more:"Taught at: Writing 10 · After a model — In the manner of…"},"wr10-model~p1":{level:10,bands:[1,2,3],topics:["stop:wr10-model","strand:writing"],key:"stop:wr10-model",where:"Writing 10 · After a model",route:"#/desk/wr10-model",cta:"In the manner of… at the writing desk",id:"wr10-model~p1",kind:"desk",src:"stop:wr10-model#prompt1",title:"A fable: two animals, one mistake, and a one-line moral",body:"The model · Your piece",more:"Taught at: Writing 10 · After a model — In the manner of…"},"wr10-model~p2":{level:10,bands:[1,2,3],topics:["stop:wr10-model","strand:writing"],key:"stop:wr10-model",where:"Writing 10 · After a model",route:"#/desk/wr10-model",cta:"In the manner of… at the writing desk",id:"wr10-model~p2",kind:"desk",src:"stop:wr10-model#prompt2",title:"A poem in the shape of “My Shadow”: something that follows you",body:"The model · Your piece",more:"Taught at: Writing 10 · After a model — In the manner of…"},"wr10-model~p3":{level:10,bands:[1,2,3],topics:["stop:wr10-model","strand:writing"],key:"stop:wr10-model",where:"Writing 10 · After a model",route:"#/desk/wr10-model",cta:"In the manner of… at the writing desk",id:"wr10-model~p3",kind:"desk",src:"stop:wr10-model#prompt3",title:"A letter from Alice to her sister, from Wonderland",body:"The model · Your piece",more:"Taught at: Writing 10 · After a model — In the manner of…"},"wr10-model~p4":{level:10,bands:[1,2,3],topics:["stop:wr10-model","strand:writing"],key:"stop:wr10-model",where:"Writing 10 · After a model",route:"#/desk/wr10-model",cta:"In the manner of… at the writing desk",id:"wr10-model~p4",kind:"desk",src:"stop:wr10-model#prompt4",title:"A new scene for the Wind in the Willows",body:"The model · Your piece",more:"Taught at: Writing 10 · After a model — In the manner of…"},"sp10-debate~idea":{level:10,bands:[1,2,3],topics:["stop:sp10-debate","strand:speaking"],key:"stop:sp10-debate",where:"Speaking 10 · Debate",route:"#/stage/sp10-debate",cta:"Both sides on the Stage",id:"sp10-debate~idea",kind:"lesson",src:"stop:sp10-debate#why",title:"Both sides",body:"First argue FOR the motion: your three best reasons. Then argue AGAINST it, just as fairly. Arguing the side you disagree with is how you learn to understand people who disagree with you.",more:"I can argue for a motion, then against it, fairly and clearly."},"sp10-debate~story":{level:10,bands:[1,2,3],topics:["stop:sp10-debate","strand:speaking"],key:"stop:sp10-debate",where:"Speaking 10 · Debate",route:"#/stage/sp10-debate",cta:"Both sides on the Stage",id:"sp10-debate~story",kind:"story",src:"stop:sp10-debate#story",title:"Both sides",body:"A debate has two sides. A great speaker can argue either — and understand both.",more:"Taught at: Speaking 10 · Debate — Both sides."},"sp10-debate~eg":{level:10,bands:[1,2,3],topics:["stop:sp10-debate","strand:speaking"],key:"stop:sp10-debate",where:"Speaking 10 · Debate",route:"#/stage/sp10-debate",cta:"Both sides on the Stage",id:"sp10-debate~eg",kind:"example",src:"stop:sp10-debate#example",title:"Both sides: for example",body:"For: three reasons. · Against: three reasons.",more:"Taught at: Speaking 10 · Debate — Both sides."},"sp10-debate~p0":{level:10,bands:[1,2,3],topics:["stop:sp10-debate","strand:speaking"],key:"stop:sp10-debate",where:"Speaking 10 · Debate",route:"#/stage/sp10-debate",cta:"Both sides on the Stage",id:"sp10-debate~p0",kind:"speech",src:"stop:sp10-debate#speak0",title:"This house believes homework should be optional",body:"I can argue for a motion, then against it, fairly and clearly.",more:"Taught at: Speaking 10 · Debate — Both sides."},"sp10-debate~p1":{level:10,bands:[1,2,3],topics:["stop:sp10-debate","strand:speaking"],key:"stop:sp10-debate",where:"Speaking 10 · Debate",route:"#/stage/sp10-debate",cta:"Both sides on the Stage",id:"sp10-debate~p1",kind:"speech",src:"stop:sp10-debate#speak1",title:"This house believes every school should have a garden",body:"I can argue for a motion, then against it, fairly and clearly.",more:"Taught at: Speaking 10 · Debate — Both sides."},"sp10-debate~p2":{level:10,bands:[1,2,3],topics:["stop:sp10-debate","strand:speaking"],key:"stop:sp10-debate",where:"Speaking 10 · Debate",route:"#/stage/sp10-debate",cta:"Both sides on the Stage",id:"sp10-debate~p2",kind:"speech",src:"stop:sp10-debate#speak2",title:"This house believes books are better than films",body:"I can argue for a motion, then against it, fairly and clearly.",more:"Taught at: Speaking 10 · Debate — Both sides."},"sp10-debate~p3":{level:10,bands:[1,2,3],topics:["stop:sp10-debate","strand:speaking"],key:"stop:sp10-debate",where:"Speaking 10 · Debate",route:"#/stage/sp10-debate",cta:"Both sides on the Stage",id:"sp10-debate~p3",kind:"speech",src:"stop:sp10-debate#speak3",title:"This house believes children should have a phone by age ten",body:"I can argue for a motion, then against it, fairly and clearly.",more:"Taught at: Speaking 10 · Debate — Both sides."},"sp10-debate~p4":{level:10,bands:[1,2,3],topics:["stop:sp10-debate","strand:speaking"],key:"stop:sp10-debate",where:"Speaking 10 · Debate",route:"#/stage/sp10-debate",cta:"Both sides on the Stage",id:"sp10-debate~p4",kind:"speech",src:"stop:sp10-debate#speak4",title:"This house believes school uniforms should be scrapped",body:"I can argue for a motion, then against it, fairly and clearly.",more:"Taught at: Speaking 10 · Debate — Both sides."},"li10-case~idea":{level:10,bands:[1,2,3],topics:["stop:li10-case","strand:literature"],key:"stop:li10-case",where:"Literature 10 · My case for this book",route:"#/desk/li10-case",cta:"My case for this book at the writing desk",id:"li10-case~idea",kind:"lesson",src:"stop:li10-case#why",title:"My case for this book",body:"A case has a claim, reasons, evidence from the book itself — a line, a moment — an answer to the other side, and a close. You are not marked on which book you choose, only on how well you argue for it.",more:"I can make the case for a book I love, with reasons and lines from it."},"li10-case~story":{level:10,bands:[1,2,3],topics:["stop:li10-case","strand:literature"],key:"stop:li10-case",where:"Literature 10 · My case for this book",route:"#/desk/li10-case",cta:"My case for this book at the writing desk",id:"li10-case~story",kind:"story",src:"stop:li10-case#story",title:"My case for this book",body:'Quill has a favourite book and a friend who will not read it. "It is old," says the friend. Quill smiles: "Then let me make my case."',more:"Taught at: Literature 10 · My case for this book — My case for this book."},"li10-case~eg":{level:10,bands:[1,2,3],topics:["stop:li10-case","strand:literature"],key:"stop:li10-case",where:"Literature 10 · My case for this book",route:"#/desk/li10-case",cta:"My case for this book at the writing desk",id:"li10-case~eg",kind:"example",src:"stop:li10-case#example",title:"My case for this book: for example",body:"Claim: Treasure Island is the best adventure ever written. · Evidence: “Fifteen men on the dead man's chest” — you hear the danger in one line.",more:"Taught at: Literature 10 · My case for this book — My case for this book."},"li10-case~p0":{level:10,bands:[1,2,3],topics:["stop:li10-case","strand:literature"],key:"stop:li10-case",where:"Literature 10 · My case for this book",route:"#/desk/li10-case",cta:"My case for this book at the writing desk",id:"li10-case~p0",kind:"desk",src:"stop:li10-case#prompt0",title:"Choose a book from the Library and argue that it is the best one for a child your age.",body:"My claim · Reason one · Reason two · The other side · My claim again",more:"Taught at: Literature 10 · My case for this book — My case for this book."},"li10-case~p1":{level:10,bands:[1,2,3],topics:["stop:li10-case","strand:literature"],key:"stop:li10-case",where:"Literature 10 · My case for this book",route:"#/desk/li10-case",cta:"My case for this book at the writing desk",id:"li10-case~p1",kind:"desk",src:"stop:li10-case#prompt1",title:"Pick a character you admire from any story in the Library, and make the case that they are the true hero of their book.",body:"My claim · Reason one · Reason two · The other side · My claim again",more:"Taught at: Literature 10 · My case for this book — My case for this book."},"li10-case~p2":{level:10,bands:[1,2,3],topics:["stop:li10-case","strand:literature"],key:"stop:li10-case",where:"Literature 10 · My case for this book",route:"#/desk/li10-case",cta:"My case for this book at the writing desk",id:"li10-case~p2",kind:"desk",src:"stop:li10-case#prompt2",title:"Choose two books you have met in the Library. Argue which one a new reader should start with, and why.",body:"My claim · Reason one · Reason two · The other side · My claim again",more:"Taught at: Literature 10 · My case for this book — My case for this book."},"li10-case~p3":{level:10,bands:[1,2,3],topics:["stop:li10-case","strand:literature"],key:"stop:li10-case",where:"Literature 10 · My case for this book",route:"#/desk/li10-case",cta:"My case for this book at the writing desk",id:"li10-case~p3",kind:"desk",src:"stop:li10-case#prompt3",title:"Choose a poem from the Library and argue that everyone should learn it by heart.",body:"My claim · Reason one · Reason two · The other side · My claim again",more:"Taught at: Literature 10 · My case for this book — My case for this book."},"li10-case~p4":{level:10,bands:[1,2,3],topics:["stop:li10-case","strand:literature"],key:"stop:li10-case",where:"Literature 10 · My case for this book",route:"#/desk/li10-case",cta:"My case for this book at the writing desk",id:"li10-case~p4",kind:"desk",src:"stop:li10-case#prompt4",title:"Pick a book written more than a hundred years ago and argue that it still matters today.",body:"My claim · Reason one · Reason two · The other side · My claim again",more:"Taught at: Literature 10 · My case for this book — My case for this book."},"li10-case~p5":{level:10,bands:[1,2,3],topics:["stop:li10-case","strand:literature"],key:"stop:li10-case",where:"Literature 10 · My case for this book",route:"#/desk/li10-case",cta:"My case for this book at the writing desk",id:"li10-case~p5",kind:"desk",src:"stop:li10-case#prompt5",title:"Choose a book some people call too hard or too old-fashioned, and make the case for giving it a chance.",body:"My claim · Reason one · Reason two · The other side · My claim again",more:"Taught at: Literature 10 · My case for this book — My case for this book."},"rd~sonnet-116":{level:10,bands:[3],topics:["stop:rd-sonnet-116","strand:reading","work:sonnets"],key:"stop:rd-sonnet-116",where:"Reading 10 · Close reading · the Library",source:"Shakespeare's Sonnets — William Shakespeare",id:"rd~sonnet-116",kind:"tale",src:"passage:sonnet-116#hook",title:"Sonnet 116: Let me not to the marriage of true minds",body:"Fourteen lines that try to say what real love is, and stake everything on it.",art:"art/story/sonnet-116-card.webp",more:"Taught at: Reading 10 · Close reading — “Sonnet 116: Let me not to the marriage of true minds”",route:"#/story/sonnet-116",cta:"Hear “Sonnet 116: Let me not to the marriage of true minds”"},"rd~sonnet-116~open":{level:10,bands:[3],topics:["stop:rd-sonnet-116","strand:reading","work:sonnets"],key:"stop:rd-sonnet-116",where:"Reading 10 · Close reading · the Library",source:"Shakespeare's Sonnets — William Shakespeare",id:"rd~sonnet-116~open",kind:"opening",src:"passage:sonnet-116#open",title:"How it begins: Sonnet 116: Let me not to the marriage of true minds",body:"Let me not to the marriage of true minds Admit impediments.",cite:"sonnets",quote:"Let me not to the marriage of true minds Admit impediments.",more:"Taught at: Reading 10 · Close reading — “Sonnet 116: Let me not to the marriage of true minds”",route:"#/story/sonnet-116",cta:"Hear the rest of “Sonnet 116: Let me not to the marriage of true minds”"},"rd~sonnet-116~q0":{level:10,bands:[3],topics:["stop:rd-sonnet-116","strand:reading","work:sonnets"],key:"stop:rd-sonnet-116",where:"Reading 10 · Close reading · the Library",source:"Shakespeare's Sonnets — William Shakespeare",id:"rd~sonnet-116~q0",kind:"question",src:"passage:sonnet-116#q0",title:"Sonnet 116: Let me not to the marriage of true minds",play:{q:"'Love is not love / Which alters when it alteration finds.' What does this mean?",opts:["True love stays when the loved one changes","Love should change to suit the seasons","Love is real only when it is brand new","Love is best when it is kept a secret"],after:""},more:"Taught at: Reading 10 · Close reading — “Sonnet 116: Let me not to the marriage of true minds”",route:"#/story/sonnet-116/do",cta:"The exercises for “Sonnet 116: Let me not to the marriage of true minds”"},"rd~sonnet-116~q1":{level:10,bands:[3],topics:["stop:rd-sonnet-116","strand:reading","work:sonnets"],key:"stop:rd-sonnet-116",where:"Reading 10 · Close reading · the Library",source:"Shakespeare's Sonnets — William Shakespeare",id:"rd~sonnet-116~q1",kind:"question",src:"passage:sonnet-116#q1",title:"Sonnet 116: Let me not to the marriage of true minds",play:{q:"Love is 'an ever-fixed mark, That looks on tempests and is never shaken'. What picture does this give?",opts:["A beacon that storms cannot move","A ship tossed about by the waves","A target hit by many arrows","A stain that will not wash out"],after:""},more:"Taught at: Reading 10 · Close reading — “Sonnet 116: Let me not to the marriage of true minds”",route:"#/story/sonnet-116/do",cta:"The exercises for “Sonnet 116: Let me not to the marriage of true minds”"},"rd~sonnet-116~q2":{level:10,bands:[3],topics:["stop:rd-sonnet-116","strand:reading","work:sonnets"],key:"stop:rd-sonnet-116",where:"Reading 10 · Close reading · the Library",source:"Shakespeare's Sonnets — William Shakespeare",id:"rd~sonnet-116~q2",kind:"question",src:"passage:sonnet-116#q2",title:"Sonnet 116: Let me not to the marriage of true minds",play:{q:"In 'the star to every wandering bark', what is a 'bark'?",opts:["A ship","A dog's cry","A tree's skin","A shepherd's hut"],after:""},more:"Taught at: Reading 10 · Close reading — “Sonnet 116: Let me not to the marriage of true minds”",route:"#/story/sonnet-116/do",cta:"The exercises for “Sonnet 116: Let me not to the marriage of true minds”"},"rd~sonnet-116~q3":{level:10,bands:[3],topics:["stop:rd-sonnet-116","strand:reading","work:sonnets"],key:"stop:rd-sonnet-116",where:"Reading 10 · Close reading · the Library",source:"Shakespeare's Sonnets — William Shakespeare",id:"rd~sonnet-116~q3",kind:"question",src:"passage:sonnet-116#q3",title:"Sonnet 116: Let me not to the marriage of true minds",play:{q:"Whose is the 'bending sickle' that cuts down rosy lips and cheeks?",opts:["Time's","Love's","The poet's","A farmer's"],after:""},more:"Taught at: Reading 10 · Close reading — “Sonnet 116: Let me not to the marriage of true minds”",route:"#/story/sonnet-116/do",cta:"The exercises for “Sonnet 116: Let me not to the marriage of true minds”"},"rd~sonnet-116~q4":{level:10,bands:[3],topics:["stop:rd-sonnet-116","strand:reading","work:sonnets"],key:"stop:rd-sonnet-116",where:"Reading 10 · Close reading · the Library",source:"Shakespeare's Sonnets — William Shakespeare",id:"rd~sonnet-116~q4",kind:"question",src:"passage:sonnet-116#q4",title:"Sonnet 116: Let me not to the marriage of true minds",play:{q:"How does the closing couplet try to prove the poem right?",opts:["If he is wrong, no one has ever loved","It quotes a famous judge's ruling","It lists every lover in history","It says the poem may well be wrong"],after:""},more:"Taught at: Reading 10 · Close reading — “Sonnet 116: Let me not to the marriage of true minds”",route:"#/story/sonnet-116/do",cta:"The exercises for “Sonnet 116: Let me not to the marriage of true minds”"},"rd~sonnet-116~talk":{level:10,bands:[3],topics:["stop:rd-sonnet-116","strand:reading","work:sonnets"],key:"stop:rd-sonnet-116",where:"Reading 10 · Close reading · the Library",source:"Shakespeare's Sonnets — William Shakespeare",id:"rd~sonnet-116~talk",kind:"talk",src:"passage:sonnet-116#talk",title:"Talk about it: Sonnet 116: Let me not to the marriage of true minds",body:"The poet says love 'alters not with his brief hours and weeks'. Is that true of the things and people you love? Choose one line and argue with it, or for it.",more:"Never marked — your own thoughts, kept on this device.",route:"#/story/sonnet-116/talk",cta:"Talk about it"},"rd~sonnet-116~w~shaken":{level:10,bands:[3],topics:["stop:rd-sonnet-116","strand:reading","work:sonnets"],key:"stop:rd-sonnet-116",where:"Reading 10 · Close reading · the Library",source:"Shakespeare's Sonnets — William Shakespeare",id:"rd~sonnet-116~w~shaken",kind:"inline",src:"pword:sonnet-116#shaken",title:"“shaken” in Sonnet 116: Let me not to the marriage of true minds",body:"Love is not love Which alters when it alteration finds, Or bends with the remover to remove: O, no! it is an ever-fixed mark, That looks on tempests and is never shaken; It is the star to every wandering bark, Whose worth's unknown, although his height be taken.",cite:"sonnets",quote:"Love is not love Which alters when it alteration finds, Or bends with the remover to remove: O, no! it is an ever-fixed mark, That looks on tempests and is never shaken; It is the star to every wandering bark, Whose worth's unknown, although his height be taken.",more:"Bee’s meaning: move or cause to move back and forth.",route:"#/story/sonnet-116",cta:"Hear “Sonnet 116: Let me not to the marriage of true minds”"},"rd~sonnet-116~w~wandering":{level:10,bands:[3],topics:["stop:rd-sonnet-116","strand:reading","work:sonnets"],key:"stop:rd-sonnet-116",where:"Reading 10 · Close reading · the Library",source:"Shakespeare's Sonnets — William Shakespeare",id:"rd~sonnet-116~w~wandering",kind:"inline",src:"pword:sonnet-116#wandering",title:"“wandering” in Sonnet 116: Let me not to the marriage of true minds",body:"Love is not love Which alters when it alteration finds, Or bends with the remover to remove: O, no! it is an ever-fixed mark, That looks on tempests and is never shaken; It is the star to every wandering bark, Whose worth's unknown, although his height be taken.",cite:"sonnets",quote:"Love is not love Which alters when it alteration finds, Or bends with the remover to remove: O, no! it is an ever-fixed mark, That looks on tempests and is never shaken; It is the star to every wandering bark, Whose worth's unknown, although his height be taken.",more:"Bee’s meaning: travelling about without any clear destination.",route:"#/story/sonnet-116",cta:"Hear “Sonnet 116: Let me not to the marriage of true minds”"},"rd~sonnet-116~w~bending":{level:10,bands:[3],topics:["stop:rd-sonnet-116","strand:reading","work:sonnets"],key:"stop:rd-sonnet-116",where:"Reading 10 · Close reading · the Library",source:"Shakespeare's Sonnets — William Shakespeare",id:"rd~sonnet-116~w~bending",kind:"inline",src:"pword:sonnet-116#bending",title:"“bending” in Sonnet 116: Let me not to the marriage of true minds",body:"Love's not Time's fool, though rosy lips and cheeks Within his bending sickle's compass come; Love alters not with his brief hours and weeks, But bears it out even to the edge of doom.",cite:"sonnets",quote:"Love's not Time's fool, though rosy lips and cheeks Within his bending sickle's compass come; Love alters not with his brief hours and weeks, But bears it out even to the edge of doom.",more:"Bee’s meaning: movement that causes the formation of a curve.",route:"#/story/sonnet-116",cta:"Hear “Sonnet 116: Let me not to the marriage of true minds”"},"rd~sonnet-116~w~cheeks":{level:10,bands:[3],topics:["stop:rd-sonnet-116","strand:reading","work:sonnets"],key:"stop:rd-sonnet-116",where:"Reading 10 · Close reading · the Library",source:"Shakespeare's Sonnets — William Shakespeare",id:"rd~sonnet-116~w~cheeks",kind:"inline",src:"pword:sonnet-116#cheeks",title:"“cheeks” in Sonnet 116: Let me not to the marriage of true minds",body:"Love's not Time's fool, though rosy lips and cheeks Within his bending sickle's compass come; Love alters not with his brief hours and weeks, But bears it out even to the edge of doom.",cite:"sonnets",quote:"Love's not Time's fool, though rosy lips and cheeks Within his bending sickle's compass come; Love alters not with his brief hours and weeks, But bears it out even to the edge of doom.",more:"Bee’s meaning: either side of the face below the eyes.",route:"#/story/sonnet-116",cta:"Hear “Sonnet 116: Let me not to the marriage of true minds”"},"rd~wordsworth-reaper":{level:10,bands:[3],topics:["stop:rd-wordsworth-reaper","strand:reading","work:wordsworth"],key:"stop:rd-wordsworth-reaper",where:"Reading 10 · Close reading · the Library",source:"Poems, in Two Volumes — William Wordsworth",id:"rd~wordsworth-reaper",kind:"tale",src:"passage:wordsworth-reaper#hook",title:"The Solitary Reaper",body:"A girl sings alone in a field. A traveller never learns the words, and never forgets them.",art:"art/story/wordsworth-reaper-card.webp",more:"Taught at: Reading 10 · Close reading — “The Solitary Reaper”",route:"#/story/wordsworth-reaper",cta:"Hear “The Solitary Reaper”"},"rd~wordsworth-reaper~open":{level:10,bands:[3],topics:["stop:rd-wordsworth-reaper","strand:reading","work:wordsworth"],key:"stop:rd-wordsworth-reaper",where:"Reading 10 · Close reading · the Library",source:"Poems, in Two Volumes — William Wordsworth",id:"rd~wordsworth-reaper~open",kind:"opening",src:"passage:wordsworth-reaper#open",title:"How it begins: The Solitary Reaper",body:"Behold her, single in the field, Yon solitary Highland Lass! Reaping and singing by herself; Stop here, or gently pass! Alone she cuts, and binds the grain, And sings a melancholy strain; O listen! for the Vale profound Is overflowing with the sound.",cite:"wordsworth",quote:"Behold her, single in the field, Yon solitary Highland Lass! Reaping and singing by herself; Stop here, or gently pass! Alone she cuts, and binds the grain, And sings a melancholy strain; O listen! for the Vale profound Is overflowing with the sound.",more:"Taught at: Reading 10 · Close reading — “The Solitary Reaper”",route:"#/story/wordsworth-reaper",cta:"Hear the rest of “The Solitary Reaper”"},"rd~wordsworth-reaper~q0":{level:10,bands:[3],topics:["stop:rd-wordsworth-reaper","strand:reading","work:wordsworth"],key:"stop:rd-wordsworth-reaper",where:"Reading 10 · Close reading · the Library",source:"Poems, in Two Volumes — William Wordsworth",id:"rd~wordsworth-reaper~q0",kind:"question",src:"passage:wordsworth-reaper#q0",title:"The Solitary Reaper",play:{q:"What is the girl doing as she sings?",opts:["Cutting and binding grain","Picking ripe apples","Herding sheep home","Spinning fine wool"],after:""},more:"Taught at: Reading 10 · Close reading — “The Solitary Reaper”",route:"#/story/wordsworth-reaper/do",cta:"The exercises for “The Solitary Reaper”"},"rd~wordsworth-reaper~q1":{level:10,bands:[3],topics:["stop:rd-wordsworth-reaper","strand:reading","work:wordsworth"],key:"stop:rd-wordsworth-reaper",where:"Reading 10 · Close reading · the Library",source:"Poems, in Two Volumes — William Wordsworth",id:"rd~wordsworth-reaper~q1",kind:"question",src:"passage:wordsworth-reaper#q1",title:"The Solitary Reaper",play:{q:"'The Vale profound / Is overflowing with the sound.' What does 'overflowing' suggest?",opts:["The song fills the whole valley","The river is in flood","The song is far too loud","Rain is pouring down the hill"],after:""},more:"Taught at: Reading 10 · Close reading — “The Solitary Reaper”",route:"#/story/wordsworth-reaper/do",cta:"The exercises for “The Solitary Reaper”"},"rd~wordsworth-reaper~q2":{level:10,bands:[3],topics:["stop:rd-wordsworth-reaper","strand:reading","work:wordsworth"],key:"stop:rd-wordsworth-reaper",where:"Reading 10 · Close reading · the Library",source:"Poems, in Two Volumes — William Wordsworth",id:"rd~wordsworth-reaper~q2",kind:"question",src:"passage:wordsworth-reaper#q2",title:"The Solitary Reaper",play:{q:"What do the lines about the nightingale and the cuckoo tell us?",opts:["Even those birds sang no sweeter","Her song sounds like chirping","Her voice is too faint to hear","Her song frightens travellers"],after:""},more:"Taught at: Reading 10 · Close reading — “The Solitary Reaper”",route:"#/story/wordsworth-reaper/do",cta:"The exercises for “The Solitary Reaper”"},"rd~wordsworth-reaper~q3":{level:10,bands:[3],topics:["stop:rd-wordsworth-reaper","strand:reading","work:wordsworth"],key:"stop:rd-wordsworth-reaper",where:"Reading 10 · Close reading · the Library",source:"Poems, in Two Volumes — William Wordsworth",id:"rd~wordsworth-reaper~q3",kind:"question",src:"passage:wordsworth-reaper#q3",title:"The Solitary Reaper",play:{q:"What does the poet do, since no one can tell him what she sings?",opts:["He imagines what it might be about","He asks her to sing it more slowly","He writes down every word","He finds a book of her songs"],after:""},more:"Taught at: Reading 10 · Close reading — “The Solitary Reaper”",route:"#/story/wordsworth-reaper/do",cta:"The exercises for “The Solitary Reaper”"},"rd~wordsworth-reaper~q4":{level:10,bands:[3],topics:["stop:rd-wordsworth-reaper","strand:reading","work:wordsworth"],key:"stop:rd-wordsworth-reaper",where:"Reading 10 · Close reading · the Library",source:"Poems, in Two Volumes — William Wordsworth",id:"rd~wordsworth-reaper~q4",kind:"question",src:"passage:wordsworth-reaper#q4",title:"The Solitary Reaper",play:{q:"'The music in my heart I bore, / Long after it was heard no more.' What has the poet kept?",opts:["The memory of the song","A copy of the words","The girl's sickle","A sheaf of her grain"],after:""},more:"Taught at: Reading 10 · Close reading — “The Solitary Reaper”",route:"#/story/wordsworth-reaper/do",cta:"The exercises for “The Solitary Reaper”"},"rd~wordsworth-reaper~talk":{level:10,bands:[3],topics:["stop:rd-wordsworth-reaper","strand:reading","work:wordsworth"],key:"stop:rd-wordsworth-reaper",where:"Reading 10 · Close reading · the Library",source:"Poems, in Two Volumes — William Wordsworth",id:"rd~wordsworth-reaper~talk",kind:"talk",src:"passage:wordsworth-reaper#talk",title:"Talk about it: The Solitary Reaper",body:"The poet never learns the words, yet the song stays with him. Why might a song we cannot understand move us so much? Which word in the poem best catches that feeling?",more:"Never marked — your own thoughts, kept on this device.",route:"#/story/wordsworth-reaper/talk",cta:"Talk about it"},"rd~wordsworth-reaper~w~highland":{level:10,bands:[3],topics:["stop:rd-wordsworth-reaper","strand:reading","work:wordsworth"],key:"stop:rd-wordsworth-reaper",where:"Reading 10 · Close reading · the Library",source:"Poems, in Two Volumes — William Wordsworth",id:"rd~wordsworth-reaper~w~highland",kind:"inline",src:"pword:wordsworth-reaper#highland",title:"“highland” in The Solitary Reaper",body:"Behold her, single in the field, Yon solitary Highland Lass!",cite:"wordsworth",quote:"Behold her, single in the field, Yon solitary Highland Lass!",more:"Bee’s meaning: elevated (e.g., mountainous) land.",route:"#/story/wordsworth-reaper",cta:"Hear “The Solitary Reaper”"},"rd~wordsworth-reaper~w~sorrow":{level:10,bands:[3],topics:["stop:rd-wordsworth-reaper","strand:reading","work:wordsworth"],key:"stop:rd-wordsworth-reaper",where:"Reading 10 · Close reading · the Library",source:"Poems, in Two Volumes — William Wordsworth",id:"rd~wordsworth-reaper~w~sorrow",kind:"inline",src:"pword:wordsworth-reaper#sorrow",title:"“sorrow” in The Solitary Reaper",body:"Some natural sorrow, loss, or pain, That has been, and may be again!",cite:"wordsworth",quote:"Some natural sorrow, loss, or pain, That has been, and may be again!",more:"Bee’s meaning: an emotion of great sadness associated with loss or bereavement.",route:"#/story/wordsworth-reaper",cta:"Hear “The Solitary Reaper”"},"rd~keats-chapman":{level:10,bands:[3],topics:["stop:rd-keats-chapman","strand:reading","work:keats"],key:"stop:rd-keats-chapman",where:"Reading 10 · Close reading · the Library",source:"Poems (1817) — John Keats",id:"rd~keats-chapman",kind:"tale",src:"passage:keats-chapman#hook",title:"On first looking into Chapman's Homer",body:"A young poet reads an old story in a new translation, and the world grows larger.",art:"art/story/keats-chapman-card.webp",more:"Taught at: Reading 10 · Close reading — “On first looking into Chapman's Homer”",route:"#/story/keats-chapman",cta:"Hear “On first looking into Chapman's Homer”"},"rd~keats-chapman~open":{level:10,bands:[3],topics:["stop:rd-keats-chapman","strand:reading","work:keats"],key:"stop:rd-keats-chapman",where:"Reading 10 · Close reading · the Library",source:"Poems (1817) — John Keats",id:"rd~keats-chapman~open",kind:"opening",src:"passage:keats-chapman#open",title:"How it begins: On first looking into Chapman's Homer",body:"Much have I traveled in the realms of gold, And many goodly states and kingdoms seen; Round many western islands have I been Which bards in fealty to Apollo hold.",cite:"keats",quote:"Much have I traveled in the realms of gold, And many goodly states and kingdoms seen; Round many western islands have I been Which bards in fealty to Apollo hold.",more:"Taught at: Reading 10 · Close reading — “On first looking into Chapman's Homer”",route:"#/story/keats-chapman",cta:"Hear the rest of “On first looking into Chapman's Homer”"},"rd~keats-chapman~q0":{level:10,bands:[3],topics:["stop:rd-keats-chapman","strand:reading","work:keats"],key:"stop:rd-keats-chapman",where:"Reading 10 · Close reading · the Library",source:"Poems (1817) — John Keats",id:"rd~keats-chapman~q0",kind:"question",src:"passage:keats-chapman#q0",title:"On first looking into Chapman's Homer",play:{q:"What are the 'realms of gold' the poet has travelled in?",opts:["The world of great books","Rich countries overseas","Gold mines in the hills","The palaces of kings"],after:""},more:"Taught at: Reading 10 · Close reading — “On first looking into Chapman's Homer”",route:"#/story/keats-chapman/do",cta:"The exercises for “On first looking into Chapman's Homer”"},"rd~keats-chapman~q1":{level:10,bands:[3],topics:["stop:rd-keats-chapman","strand:reading","work:keats"],key:"stop:rd-keats-chapman",where:"Reading 10 · Close reading · the Library",source:"Poems (1817) — John Keats",id:"rd~keats-chapman~q1",kind:"question",src:"passage:keats-chapman#q1",title:"On first looking into Chapman's Homer",play:{q:"Before he read Chapman, how did the poet know of Homer?",opts:["He had only been told of him","He had read Homer in Greek","He had met Homer once","He had never heard of him"],after:""},more:"Taught at: Reading 10 · Close reading — “On first looking into Chapman's Homer”",route:"#/story/keats-chapman/do",cta:"The exercises for “On first looking into Chapman's Homer”"},"rd~keats-chapman~q2":{level:10,bands:[3],topics:["stop:rd-keats-chapman","strand:reading","work:keats"],key:"stop:rd-keats-chapman",where:"Reading 10 · Close reading · the Library",source:"Poems (1817) — John Keats",id:"rd~keats-chapman~q2",kind:"question",src:"passage:keats-chapman#q2",title:"On first looking into Chapman's Homer",play:{q:"Why does he compare himself to 'some watcher of the skies' who sees a new planet?",opts:["The book felt like a new discovery","He read the book under the stars","He wanted to become an astronomer","Chapman wrote about the planets"],after:""},more:"Taught at: Reading 10 · Close reading — “On first looking into Chapman's Homer”",route:"#/story/keats-chapman/do",cta:"The exercises for “On first looking into Chapman's Homer”"},"rd~keats-chapman~q3":{level:10,bands:[3],topics:["stop:rd-keats-chapman","strand:reading","work:keats"],key:"stop:rd-keats-chapman",where:"Reading 10 · Close reading · the Library",source:"Poems (1817) — John Keats",id:"rd~keats-chapman~q3",kind:"question",src:"passage:keats-chapman#q3",title:"On first looking into Chapman's Homer",play:{q:"In 'swims into his ken', what does 'ken' mean?",opts:["Range of sight","His family","His notebook","His garden"],after:""},more:"Taught at: Reading 10 · Close reading — “On first looking into Chapman's Homer”",route:"#/story/keats-chapman/do",cta:"The exercises for “On first looking into Chapman's Homer”"},"rd~keats-chapman~q4":{level:10,bands:[3],topics:["stop:rd-keats-chapman","strand:reading","work:keats"],key:"stop:rd-keats-chapman",where:"Reading 10 · Close reading · the Library",source:"Poems (1817) — John Keats",id:"rd~keats-chapman~q4",kind:"question",src:"passage:keats-chapman#q4",title:"On first looking into Chapman's Homer",play:{q:"Why are the men on the peak silent?",opts:["They are struck dumb with wonder","They are too tired to speak","They were told to keep quiet","They are angry with their leader"],after:""},more:"Taught at: Reading 10 · Close reading — “On first looking into Chapman's Homer”",route:"#/story/keats-chapman/do",cta:"The exercises for “On first looking into Chapman's Homer”"},"rd~keats-chapman~talk":{level:10,bands:[3],topics:["stop:rd-keats-chapman","strand:reading","work:keats"],key:"stop:rd-keats-chapman",where:"Reading 10 · Close reading · the Library",source:"Poems (1817) — John Keats",id:"rd~keats-chapman~talk",kind:"talk",src:"passage:keats-chapman#talk",title:"Talk about it: On first looking into Chapman's Homer",body:"Keats needs a planet and an ocean to describe reading one book. What would you compare the feeling of a great book to? Is his comparison too big, or just right?",more:"Never marked — your own thoughts, kept on this device.",route:"#/story/keats-chapman/talk",cta:"Talk about it"},"rd~keats-chapman~w~realms":{level:10,bands:[3],topics:["stop:rd-keats-chapman","strand:reading","work:keats"],key:"stop:rd-keats-chapman",where:"Reading 10 · Close reading · the Library",source:"Poems (1817) — John Keats",id:"rd~keats-chapman~w~realms",kind:"inline",src:"pword:keats-chapman#realms",title:"“realms” in On first looking into Chapman's Homer",body:"Much have I traveled in the realms of gold, And many goodly states and kingdoms seen; Round many western islands have I been Which bards in fealty to Apollo hold.",cite:"keats",quote:"Much have I traveled in the realms of gold, And many goodly states and kingdoms seen; Round many western islands have I been Which bards in fealty to Apollo hold.",more:"Bee’s meaning: a domain in which something is dominant.",route:"#/story/keats-chapman",cta:"Hear “On first looking into Chapman's Homer”"},"rd~keats-chapman~w~islands":{level:10,bands:[3],topics:["stop:rd-keats-chapman","strand:reading","work:keats"],key:"stop:rd-keats-chapman",where:"Reading 10 · Close reading · the Library",source:"Poems (1817) — John Keats",id:"rd~keats-chapman~w~islands",kind:"inline",src:"pword:keats-chapman#islands",title:"“islands” in On first looking into Chapman's Homer",body:"Much have I traveled in the realms of gold, And many goodly states and kingdoms seen; Round many western islands have I been Which bards in fealty to Apollo hold.",cite:"keats",quote:"Much have I traveled in the realms of gold, And many goodly states and kingdoms seen; Round many western islands have I been Which bards in fealty to Apollo hold.",more:"Bee’s meaning: a land mass (smaller than a continent) that is surrounded by water.",route:"#/story/keats-chapman",cta:"Hear “On first looking into Chapman's Homer”"},"rd~blake-holy-thursday":{level:10,bands:[3],topics:["stop:rd-blake-holy-thursday","strand:reading","work:blake"],key:"stop:rd-blake-holy-thursday",where:"Reading 10 · Close reading · the Library",source:"Songs of Innocence and of Experience — William Blake",id:"rd~blake-holy-thursday",kind:"tale",src:"passage:blake-holy-thursday#hook",title:"Holy Thursday (Songs of Experience)",body:"Hungry children in a rich country, and a poet who will not stop asking why.",art:"art/story/blake-holy-thursday-card.webp",more:"Taught at: Reading 10 · Close reading — “Holy Thursday (Songs of Experience)”",route:"#/story/blake-holy-thursday",cta:"Hear “Holy Thursday (Songs of Experience)”"},"rd~blake-holy-thursday~open":{level:10,bands:[3],topics:["stop:rd-blake-holy-thursday","strand:reading","work:blake"],key:"stop:rd-blake-holy-thursday",where:"Reading 10 · Close reading · the Library",source:"Songs of Innocence and of Experience — William Blake",id:"rd~blake-holy-thursday~open",kind:"opening",src:"passage:blake-holy-thursday#open",title:"How it begins: Holy Thursday (Songs of Experience)",body:"Is this a holy thing to see In a rich and fruitful land,-- Babes reduced to misery, Fed with cold and usurous hand? Is that trembling cry a song?",cite:"blake",quote:"Is this a holy thing to see In a rich and fruitful land,-- Babes reduced to misery, Fed with cold and usurous hand? Is that trembling cry a song?",more:"Taught at: Reading 10 · Close reading — “Holy Thursday (Songs of Experience)”",route:"#/story/blake-holy-thursday",cta:"Hear the rest of “Holy Thursday (Songs of Experience)”"},"rd~blake-holy-thursday~q0":{level:10,bands:[3],topics:["stop:rd-blake-holy-thursday","strand:reading","work:blake"],key:"stop:rd-blake-holy-thursday",where:"Reading 10 · Close reading · the Library",source:"Songs of Innocence and of Experience — William Blake",id:"rd~blake-holy-thursday~q0",kind:"question",src:"passage:blake-holy-thursday#q0",title:"Holy Thursday (Songs of Experience)",play:{q:"What is wrong with 'Babes reduced to misery' in 'a rich and fruitful land'?",opts:["Children starve in a land of plenty","The land has had a bad harvest","The babies are crying for toys","Rich children are unhappy too"],after:""},more:"Taught at: Reading 10 · Close reading — “Holy Thursday (Songs of Experience)”",route:"#/story/blake-holy-thursday/do",cta:"The exercises for “Holy Thursday (Songs of Experience)”"},"rd~blake-holy-thursday~q1":{level:10,bands:[3],topics:["stop:rd-blake-holy-thursday","strand:reading","work:blake"],key:"stop:rd-blake-holy-thursday",where:"Reading 10 · Close reading · the Library",source:"Songs of Innocence and of Experience — William Blake",id:"rd~blake-holy-thursday~q1",kind:"question",src:"passage:blake-holy-thursday#q1",title:"Holy Thursday (Songs of Experience)",play:{q:"'Is that trembling cry a song?' What is the poet suggesting?",opts:["The children's singing sounds like crying","The children sing perfectly in tune","The choir is singing a sad hymn","A bird is singing in the trees"],after:""},more:"Taught at: Reading 10 · Close reading — “Holy Thursday (Songs of Experience)”",route:"#/story/blake-holy-thursday/do",cta:"The exercises for “Holy Thursday (Songs of Experience)”"},"rd~blake-holy-thursday~q2":{level:10,bands:[3],topics:["stop:rd-blake-holy-thursday","strand:reading","work:blake"],key:"stop:rd-blake-holy-thursday",where:"Reading 10 · Close reading · the Library",source:"Songs of Innocence and of Experience — William Blake",id:"rd~blake-holy-thursday~q2",kind:"question",src:"passage:blake-holy-thursday#q2",title:"Holy Thursday (Songs of Experience)",play:{q:"What does 'Fed with cold and usurous hand' say about those who feed the children?",opts:["They give without kindness, for profit","Their hands are cold from the winter","They cook the food far too little","They give the children too much"],after:""},more:"Taught at: Reading 10 · Close reading — “Holy Thursday (Songs of Experience)”",route:"#/story/blake-holy-thursday/do",cta:"The exercises for “Holy Thursday (Songs of Experience)”"},"rd~blake-holy-thursday~q3":{level:10,bands:[3],topics:["stop:rd-blake-holy-thursday","strand:reading","work:blake"],key:"stop:rd-blake-holy-thursday",where:"Reading 10 · Close reading · the Library",source:"Songs of Innocence and of Experience — William Blake",id:"rd~blake-holy-thursday~q3",kind:"question",src:"passage:blake-holy-thursday#q3",title:"Holy Thursday (Songs of Experience)",play:{q:"In the third verse, what does 'eternal winter' stand for?",opts:["Endless hardship for the poor","A cold climate all year","A long Christmas holiday","A real snowstorm in the city"],after:""},more:"Taught at: Reading 10 · Close reading — “Holy Thursday (Songs of Experience)”",route:"#/story/blake-holy-thursday/do",cta:"The exercises for “Holy Thursday (Songs of Experience)”"},"rd~blake-holy-thursday~q4":{level:10,bands:[3],topics:["stop:rd-blake-holy-thursday","strand:reading","work:blake"],key:"stop:rd-blake-holy-thursday",where:"Reading 10 · Close reading · the Library",source:"Songs of Innocence and of Experience — William Blake",id:"rd~blake-holy-thursday~q4",kind:"question",src:"passage:blake-holy-thursday#q4",title:"Holy Thursday (Songs of Experience)",play:{q:"What does the last verse say is true wherever the sun shines and the rain falls?",opts:["No child should ever go hungry","The crops will all be ruined","The children will sing louder","The poor will leave the land"],after:""},more:"Taught at: Reading 10 · Close reading — “Holy Thursday (Songs of Experience)”",route:"#/story/blake-holy-thursday/do",cta:"The exercises for “Holy Thursday (Songs of Experience)”"},"rd~blake-holy-thursday~talk":{level:10,bands:[3],topics:["stop:rd-blake-holy-thursday","strand:reading","work:blake"],key:"stop:rd-blake-holy-thursday",where:"Reading 10 · Close reading · the Library",source:"Songs of Innocence and of Experience — William Blake",id:"rd~blake-holy-thursday~talk",kind:"talk",src:"passage:blake-holy-thursday#talk",title:"Talk about it: Holy Thursday (Songs of Experience)",body:"Blake asks questions instead of giving answers. Why might a question make a reader think harder than a statement would?",more:"Never marked — your own thoughts, kept on this device.",route:"#/story/blake-holy-thursday/talk",cta:"Talk about it"},"rd~blake-holy-thursday~w~poverty":{level:10,bands:[3],topics:["stop:rd-blake-holy-thursday","strand:reading","work:blake"],key:"stop:rd-blake-holy-thursday",where:"Reading 10 · Close reading · the Library",source:"Songs of Innocence and of Experience — William Blake",id:"rd~blake-holy-thursday~w~poverty",kind:"inline",src:"pword:blake-holy-thursday#poverty",title:"“poverty” in Holy Thursday (Songs of Experience)",body:"It is a land of poverty!",cite:"blake",quote:"It is a land of poverty!",more:"Bee’s meaning: the state of having little or no money and few or no material possessions.",route:"#/story/blake-holy-thursday",cta:"Hear “Holy Thursday (Songs of Experience)”"},"rd~blake-holy-thursday~w~eternal":{level:10,bands:[3],topics:["stop:rd-blake-holy-thursday","strand:reading","work:blake"],key:"stop:rd-blake-holy-thursday",where:"Reading 10 · Close reading · the Library",source:"Songs of Innocence and of Experience — William Blake",id:"rd~blake-holy-thursday~w~eternal",kind:"inline",src:"pword:blake-holy-thursday#eternal",title:"“eternal” in Holy Thursday (Songs of Experience)",body:"And their sun does never shine, And their fields are bleak and bare, And their ways are filled with thorns, It is eternal winter there.",cite:"blake",quote:"And their sun does never shine, And their fields are bleak and bare, And their ways are filled with thorns, It is eternal winter there.",more:"Bee’s meaning: continuing forever or indefinitely.",route:"#/story/blake-holy-thursday",cta:"Hear “Holy Thursday (Songs of Experience)”"},"rd~blake-holy-thursday~w~hunger":{level:10,bands:[3],topics:["stop:rd-blake-holy-thursday","strand:reading","work:blake"],key:"stop:rd-blake-holy-thursday",where:"Reading 10 · Close reading · the Library",source:"Songs of Innocence and of Experience — William Blake",id:"rd~blake-holy-thursday~w~hunger",kind:"inline",src:"pword:blake-holy-thursday#hunger",title:"“hunger” in Holy Thursday (Songs of Experience)",body:"For where'er the sun does shine, And where'er the rain does fall, Babe can never hunger there, Nor poverty the mind appal.",cite:"blake",quote:"For where'er the sun does shine, And where'er the rain does fall, Babe can never hunger there, Nor poverty the mind appal.",more:"Bee’s meaning: a physiological need for food; the consequence of food deprivation.",route:"#/story/blake-holy-thursday",cta:"Hear “Holy Thursday (Songs of Experience)”"},"rd~blake-holy-thursday~w~reduced":{level:10,bands:[3],topics:["stop:rd-blake-holy-thursday","strand:reading","work:blake"],key:"stop:rd-blake-holy-thursday",where:"Reading 10 · Close reading · the Library",source:"Songs of Innocence and of Experience — William Blake",id:"rd~blake-holy-thursday~w~reduced",kind:"inline",src:"pword:blake-holy-thursday#reduced",title:"“reduced” in Holy Thursday (Songs of Experience)",body:"Is this a holy thing to see In a rich and fruitful land,-- Babes reduced to misery, Fed with cold and usurous hand?",cite:"blake",quote:"Is this a holy thing to see In a rich and fruitful land,-- Babes reduced to misery, Fed with cold and usurous hand?",more:"Bee’s meaning: cut down on; make a reduction in.",route:"#/story/blake-holy-thursday",cta:"Hear “Holy Thursday (Songs of Experience)”"}};export{e as default};
